wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let PublishedDigest {
            date,
            considered,
            published,
        } = published;

        let mut recorded: u32 = 0;

        // Only mark items seen once the digest actually went out; an
        // unpublished run leaves the store untouched so the next run
        // reconsiders the same items.
        if published {
            let mut done: Vec<&str> = Vec::with_capacity(considered.len());
            for id in considered.iter() {
                let id = id.as_str();
                if id.is_empty() || done.contains(&id) {
                    continue;
                }
                done.push(id);
                state_rw::put(id, &date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport { date, recorded }
    }
}

export!(Node);
